INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_naturel', 'Sang Naturel · Vortigern', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_naturel","portes":{"A":"Les éléments","B":"Le territoire"},"identite":"éléments et accord avec le territoire","description":"Sang vif de Vortigern lié aux éléments et à l’accord primordial. Il exprime une relation instinctive à des forces naturelles que le Khinae apprend progressivement à canaliser plutôt qu’à simplement subir.","changements":"notes retirées (« ces échelles et le jet sont nouveaux ») ; renvoi au Pelage Noir retiré."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'appel_elementaire', 'Appel élémentaire', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R — 1 PA","activation":null,"texte_court":"1 PA, 10 m. Oriente un élément déjà présent : 10 litres d''eau ou de terre meuble, une petite flamme, un courant d''air local. Opération incertaine : Volonté + Force Mentale, difficulté 15. Ni création d''élément ni dégâts directs.","texte_reference":"Pour 1 PA à 10 m, orientez un élément déjà présent : jusqu’à 10 litres d’eau ou de terre meuble, une petite flamme ou un courant d’air local. Une opération incertaine demande Volonté + Force Mentale, difficulté 15 ; ni création d’élément, ni dégâts ou incapacité offensifs directs.\nCes échelles et le jet sont nouveaux. Les usages indirects restent soumis à la physique de la scène ; une pierre façonnée, un bâtiment ou tout l’air d’une pièce ne sont pas une poignée de terre ou un courant local.","lore":"Vortigern n’invente pas l’élément : il réveille celui qui est déjà là. Eau, air, feu, terre ou force naturelle présente répond à une intention qui l’oriente sans la transformer en matière sortie du néant.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_appel_elementaire']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'dechainement_elementaire', 'Déchaînement élémentaire', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"avec assez d''élément présent, 1 PA : attaque DGT 6 à 20 m, Volonté + Force Mentale contre Défense physique. Ou 1 PA en Réaction : Défense active physique à +3, si l''élément peut vraiment te couvrir.","texte_reference":"Avec un élément présent en quantité suffisante, dépensez 1 PA pour une attaque élémentaire DGT 6 à 20 m contre la Défense physique, ou 1 PA en Réaction pour une Défense active physique à +3 que cet élément peut réellement soutenir. Le PA de Réaction comprend cette défense.\nLe jet offensif est Volonté + Force Mentale contre la Défense physique. Pas de seconde attaque, de zone gratuite, de dégâts répétés ou de protection mentale. Une petite flamme ne pare pas une balle par principe ; les propriétés de l’élément et les protections adaptées restent déterminantes.","lore":"L’accord élémentaire cesse d’être une manipulation délicate et devient force de confrontation. L’élément disponible est poussé jusqu’à produire une défense ou une attaque qui reste fidèle à ce qu’il est réellement dans l’environnement.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_dechainement_elementaire']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'marque_tellurique', 'Marque tellurique', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR","activation":null,"texte_court":"dix minutes sur place pour marquer un territoire de 50 m de rayon jusqu''à la fin du scénario. Jusqu''à 100 m de lui, tu sens les perturbations surnaturelles majeures qui le touchent, sans leur source. Un territoire à la fois.","texte_reference":"Après dix minutes sur un site parcouru, marquez un territoire cohérent de 50 m de rayon maximum jusqu’à la fin du scénario. À 100 m maximum de ce territoire, ressentez les perturbations surnaturelles majeures qui l’affectent, sans en identifier automatiquement la source.\nUn territoire marqué à la fois ;  La Marque n’invente aucune propriété de Meute ou de Pelage Noir chez une autre Lignée.","lore":"Le porteur inscrit sa présence dans un territoire puis continue d’en sentir l’état. Une perturbation surnaturelle majeure y résonne jusque dans son instinct, comme une secousse transmise par un lien plus profond que la simple géographie.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_marque_tellurique']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'domaine_primordial', 'Domaine primordial', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — 1/scène","activation":null,"texte_court":"dans ton territoire, 1 PA en Réaction, 1/scène. Volonté + Force Mentale contre la Puissance d''une manifestation locale que tu perçois : elle échoue, ou son effet continu est suspendu jusqu''à la fin de ton prochain round. Un effet, pas sa source.","texte_reference":"Dans votre territoire marqué, pour 1 PA en Réaction une fois par scène, opposez Volonté + Force Mentale à la Puissance d’une manifestation surnaturelle locale directement perçue. En réussite, empêchez cette résolution locale ou suspendez l’effet local continu jusqu’à la fin de votre prochain round.\nUn seul effet dans le site, non sa source entière, sa Nature, une Marque fondamentale ou un pouvoir à l’échelle mondiale. Les immunités et exceptions explicites restent prioritaires.","lore":"Un lieu auquel le porteur s’est accordé devient plus difficile à violenter surnaturellement. La manifestation étrangère rencontre la résistance diffuse du territoire lui-même, comme si sol, air et présence naturelle refusaient ensemble l’intrusion.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_domaine_primordial']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_alpha', 'Sang Alpha · Ohtana', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_alpha","portes":{"A":"L''injonction","B":"Le ralliement"},"identite":"dominance et cohésion","description":"Sang d’Ohtana consacré à la dominance et à la cohésion. Chez un Loup il s’exprime naturellement autour de la Meute ; chez un autre descendant de Khinae, il suit la logique sociale propre à sa Lignée plutôt que d’inventer artificiellement une hiérarchie lupine.","changements":"Regard d''Alpha : **ressort propre validé** (la hiérarchie : la cible doit déjà céder), qui le sépare de la Domination du Vampire ; Autorité absolue en hérite, ce qui la sépare de l''Ordre impérieux (Krovni). Renvois retirés (Hurlement du Rempart, « non-Loups »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'regard_d_alpha', 'Regard d''Alpha', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"1 PA, 10 m, Charisme + Autorité contre Défense occulte. **Seulement sur une cible qui a reculé devant toi ou montré sa peur** (Tendue ou Paniquée face à toi). Elle exécute un geste bref à sa prochaine occasion : lâcher, reculer, s''arrêter. Expire à la fin de son prochain round. Jamais suicide, automutilation ou trahison fondamentale.","texte_reference":"Pour 1 PA à 10 m, Charisme + Autorité contre la Défense occulte impose à une cible qui perçoit votre injonction un geste bref réalisable à sa prochaine occasion : lâcher, reculer ou s’arrêter. L’ordre expire à la fin de son prochain round et ne peut imposer suicide, automutilation ou trahison fondamentale.\nUn geste, pas un tour complet contrôlé ; aucun PA supplémentaire donné à la cible. Une même injonction ne se répète pas pour contourner la résistance ou la règle de non-spam.","lore":"Le regard d’Ohtana porte l’ancienne logique du dominant qui exige un geste immédiat. La cible entend bien ses propres pensées, mais une impulsion plus profonde lui souffle de reculer, lâcher ou obéir avant d’avoir pesé la décision.","statut_regle":"correction","changements":"Regard d''Alpha : **ressort propre validé** (la hiérarchie : la cible doit déjà céder), qui le sépare de la Domination du Vampire ; Autorité absolue en hérite, ce qui la sépare de l''Ordre impérieux (Krovni). Renvois retirés (Hurlement du Rempart, « non-Loups »)."}'::jsonb, 'published', ARRAY['khinae_blood_regard_d_alpha']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'autorite_absolue', 'Autorité absolue', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"1 PA, 1/scène. Ton Regard impose une consigne cohérente, réalisable pendant le prochain round de la cible, qui paie ses actions. Elle peut dépenser 1 PA pour s''en libérer : Volonté + Force Mentale contre ton résultat initial. Mêmes limites et même condition que le Regard.","texte_reference":"Pour 1 PA, une fois par scène, Regard d’Alpha peut imposer une consigne cohérente réalisable pendant le prochain round de la cible. Celle-ci peut dépenser 1 PA pour tenter de s’en libérer par Volonté + Force Mentale contre le résultat initial ; les limites fondamentales du Regard restent applicables.\nLa cible paie normalement les actions requises par la consigne. Aucune fidélité durable ni contrôle de mémoire ; la durée expire au plus tard à la fin du prochain round. ","lore":"L’héritage d’Ohtana pousse le commandement au-delà du réflexe de meute. Une injonction déjà acceptée par l’instinct peut devenir assez structurée pour guider plusieurs gestes, et résister consciemment à cette poussée demande un effort perceptible.","statut_regle":"correction","changements":"Regard d''Alpha : **ressort propre validé** (la hiérarchie : la cible doit déjà céder), qui le sépare de la Domination du Vampire ; Autorité absolue en hérite, ce qui la sépare de l''Ordre impérieux (Krovni). Renvois retirés (Hurlement du Rempart, « non-Loups »)."}'::jsonb, 'published', ARRAY['khinae_blood_autorite_absolue']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'ralliement_de_meute', 'Ralliement de meute', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR","activation":null,"texte_court":"1 PA, 1/scène. Un proche reconnu qui te perçoit à 10 m retente aussitôt, à +3, de se libérer d''une peur, d''une Frénésie ou d''une domination.","texte_reference":"Pour 1 PA, une fois par scène, un proche reconnu qui vous perçoit à 10 m peut immédiatement tenter avec +3 une nouvelle résistance pour se libérer d’une peur, Frénésie ou domination, même si l’effet n’en prévoit pas à ce moment. Un seul effet est visé ; une résistance équivalente ne s’ajoute pas au +3.\nC’est un nouveau test de libération, pas une seconde relance du test initial. Pour les non-Loups, employer les partenaires réellement reconnus de leur Lignée, sans leur imposer Appel de la Meute.","lore":"Un membre de la meute vacille moins longtemps lorsque l’Alpha le rappelle à lui. Peur, frénésie ou volonté étrangère rencontrent soudain le souvenir concret d’un groupe auquel il appartient et qui attend encore quelque chose de lui.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_ralliement_de_meute']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'hurlement_d_alpha', 'Hurlement d''Alpha', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — 1/scène","activation":null,"texte_court":"1 PA, 1/scène. Jusqu''à trois proches à 10 m qui t''entendent reçoivent chacun ce Ralliement.","texte_reference":"Pour 1 PA, une fois par scène, jusqu’à trois proches reconnus à 10 m qui vous entendent reçoivent chacun l’effet de Ralliement de meute. Chacun fait sa propre résistance à +3 contre un effet qui l’affecte ; aucun bonus permanent ni succès automatique.\nNe cumule pas deux Ralliements sur un même test ; le Hurlement du Rempart reste la prévention de Panique, pas la libération de domination.","lore":"Le hurlement ne transmet pas des mots mais une certitude collective. Ceux que le porteur reconnaît comme sa meute retrouvent en l’entendant le même axe intérieur, comme si la présence de l’Alpha leur rappelait simultanément pourquoi ils tiennent encore.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_hurlement_d_alpha']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_revelateur', 'Sang Révélateur · Ceallachán', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_revelateur","portes":{"A":"Les pensées","B":"La vérité"},"identite":"pensées et mensonges surnaturels","description":"Sang de Ceallachán lié à la pensée et à la destruction des mensonges surnaturels. Il pousse l’héritage Khinae vers la lecture de ce qui se cache derrière l’apparence et la confrontation directe aux tromperies occultes.","changements":"aucun sur le fond. *Retiré le 30/10* : la condition « lecture du corps » que j''avais ajoutée pour distinguer ces Lectures de celles du Vampire ; les deux catalogues V1 les ont volontairement semblables (décision A4). Dissipation reste distincte de celle du Vampire (elle dissipe, elle ne suspend pas un pouvoir)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'lecture_superficielle', 'Lecture superficielle', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"1 PA, 10 m, Volonté + Force Mentale contre Défense occulte. Pensées, impressions et émotions présentes, jusqu''à ta prochaine activation. Une pensée peut être fausse.","texte_reference":"Pour 1 PA, opposez Volonté + Force Mentale à la Défense occulte d’une créature directement perçue à 10 m pour lire ses pensées, impressions et émotions présentes jusqu’à votre prochaine activation. Cela ne donne ni souvenirs enfouis ni certitude qu’une pensée est vraie.\nUne lecture prolongée repaie son activation ; protections mentales et incompatibilités explicites s’appliquent. Pas de bonus universel de négociation.","lore":"Les pensées immédiates ont une texture que Ceallachán rend perceptible. Intention, émotion et fragments verbaux affleurent assez pour comprendre l’état mental présent sans ouvrir automatiquement les souvenirs qui l’ont construit.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_lecture_superficielle']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'lecture_profonde', 'Lecture profonde', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"2 PA, 10 m, même jet et même condition. Un souvenir ou une motivation précise ; le DR en fixe la profondeur et la netteté.","texte_reference":"Pour 2 PA à 10 m, opposez Volonté + Force Mentale à la Défense occulte pour rechercher un souvenir ou une motivation déterminés. Le DR précise profondeur et netteté des éléments réellement présents, sans fournir automatiquement leur interprétation ni toute l’identité de Vérité.\nUne recherche ciblée par activation. Les protections qui occultent ou modifient le souvenir restent pertinentes ; la lecture d’un souvenir erroné n’en fait pas un fait objectif.","lore":"Le porteur descend sous les pensées présentes jusqu’aux souvenirs, motivations et indices plus enfouis. Ce qu’il reçoit reste fait d’images et de sensations à interpréter, jamais d’une explication parfaite offerte par l’esprit observé.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_lecture_profonde']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'il_de_verite', 'Œil de Vérité', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR","activation":null,"texte_court":"à 10 m, tu repères les signes d''une illusion ou d''une transformation surnaturelle locale. Une dissimulation active oppose sa Puissance à ton Esprit + Perception. Ni l''auteur ni la vraie forme ; le Voile ordinaire n''est pas une illusion.","texte_reference":"En SR/R, repérez à 10 m les signes perceptibles d’une illusion ou transformation surnaturelle locale ; une dissimulation active oppose sa Puissance à Esprit + Perception. Le Voile ordinaire n’est pas une illusion ainsi dévoilée et la vraie morphologie n’est pas automatiquement révélée.\nDétecter une transformation n’en identifie ni l’auteur ni les pouvoirs. Les signes directement visibles ne demandent pas systématiquement un jet supplémentaire.","lore":"Le regard reconnaît la présence d’une falsification surnaturelle avant d’en connaître la méthode. Quelque chose paraît décalé dans l’image, la chair ou la scène, avertissement net qu’une illusion ou transformation travaille ici.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_il_de_verite']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'dissipation_revelatrice', 'Dissipation révélatrice', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"1 PA au contact, Volonté + Force Mentale contre la Puissance d''une illusion ou transformation temporaire identifiée : tu la dissipes. Rien de permanent, ni état V/SR/R, ni Nature.","texte_reference":"Pour 1 PA au contact, opposez Volonté + Force Mentale à la Puissance d’une illusion ou transformation surnaturelle temporaire identifiée pour la dissiper. Aucun état V/SR/R, Nature, Marque fondamentale ou dommage matériel déjà permanent n’est effacé.\nPas de jet physique ajouté contre le même effet direct : les conditions réelles d’accès au contact restent nécessaires. Le Talent ne remplace pas un exorcisme ou une purification de Corruption.","lore":"Ceallachán ne se contente plus de voir le mensonge surnaturel : le contact lui permet de le contester. Illusion ou transformation doit alors conserver sa cohérence face à une Nature qui cherche activement à remettre l’apparence en accord avec ce qu’elle cache.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_dissipation_revelatrice']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_ecarlate', 'Sang Écarlate · Keyna', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_ecarlate","portes":{"A":"Le sang","B":"La fureur"},"identite":"puissance physique et perception du sang","description":"Sang de Keyna centré sur la puissance physique et la perception du sang. Il fait du corps et de la chasse hématique une même spécialisation, plus brutale que la plupart des Sangs de perception.","changements":"notes de serveur retirées. *Retiré le 30/10* : la perception « par le flair » et l''interdiction de Déferlement en hybride, que j''avais ajoutées pour distinguer ce Sang de l''Écarlate vampirique. Les deux sont volontairement proches (décision A4), le Sang est partagé avec les autres Lignées khinae (un Rapace ne flaire pas), et l''interdiction en hybride venait d''un audit non validé. Le cumul du +3 avec l''hybride reste à observer en partie, pas à corriger d''avance."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'vision_du_sang', 'Vision du Sang', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"à 10 m, le sang frais et la circulation des vivants, malgré l''obscurité, la fumée ou une cloison légère (10 cm au plus) qui laisse passer l''air. Présence et position grossière.","texte_reference":"En SR/R, percevez à 10 m le sang frais et la circulation des vivants malgré l’obscurité ou une cloison légère de 10 cm au plus. Cela donne une présence et sa localisation grossière, pas l’identité, les PV ou une vision à travers un blindage.\nTous les matériaux de 10 cm ne sont pas franchissables : blindage et écran surnaturel adapté restent bloquants.","lore":"La circulation des vivants se dessine derrière leur enveloppe. Le porteur distingue sang frais, pulsations et masses vascularisées malgré une obscurité légère ou un obstacle mince, lisant la présence vitale avant les détails du visage.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_vision_du_sang']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'traque_hematique', 'Traque hématique', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"un sang que tu as perçu, tu reconnais sa signature et suis sa trace malgré les perturbations ordinaires. Sans trace, aucune direction.","texte_reference":"Reconnaît un sang précis et suit sa trace malgré les perturbations ordinaires.\nEnregistrer la signature réellement étudiée ; conserver les contraintes de trace existante, de portée des perceptions et les oppositions pertinentes. Ni Nature ni Compétence copiée par la reconnaissance.","lore":"Chaque individu possède dans son sang une signature que Keyna permet de retenir. Une fois reconnue, elle demeure distincte au milieu d’autres odeurs et traces, assez personnelle pour guider la poursuite tant qu’un chemin matériel subsiste.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_traque_hematique']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'deferlement_ecarlate', 'Déferlement écarlate', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — 1 PA","activation":null,"texte_court":"1/round, avant un test physique, +3 sans PA d''activation ; le test garde son coût.","texte_reference":"Une fois par round, avant un test physique, obtenez +3 sans PA d’activation supplémentaire. Le test conserve son coût normal et les bonus physiques substantiellement équivalents ne se cumulent pas.\nLe bonus ne devient ni +3 à tous les tests du round ni +3 Vigueur permanent. Pas de déclenchement après connaissance du résultat.","lore":"Keyna ouvre brièvement les réserves du corps au même instant. Force, vitesse ou coordination peuvent profiter de cette poussée hématique immédiate, comme si le sang avait anticipé la nécessité d’un effort avant même que les muscles l’exigent.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_deferlement_ecarlate']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'surregime', 'Surrégime', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — 1/scène","activation":null,"texte_court":"1/scène, sans PA, +1 PA à utiliser avant la fin du round. Avec le rythme de l''hybride ou du Corps Enchaîné : 5 PA au plus.","texte_reference":"Une fois par scène, sans PA d’activation, gagnez +1 PA à employer dans une fenêtre d’action normale avant la fin du round. Il peut s’ajouter au rythme de votre corps Khinae — Hybride ou Enchaîné, jamais les deux — pour un maximum normal de 5 PA.\nAucun cumul avec un troisième gain direct de PA, aucune action rétroactive et aucun +1 hybride avant le moment où il est normalement acquis.","lore":"Le prédateur accélère au-delà du rythme normal de la scène. Un geste supplémentaire apparaît là où le corps semblait déjà avoir dépensé tout son temps, résultat d’une circulation et d’un instinct forcés à fonctionner ensemble à une cadence impossible.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_surregime']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_sculpteur', 'Sang Sculpteur · Svenn', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_sculpteur","portes":{"A":"La matière","B":"La chair"},"identite":"modelage de matière et de chair","description":"Sang de Svenn consacré au modelage de matière et de chair. Il traite le corps et certaines structures physiques comme des formes susceptibles d’être altérées par un héritage Khinae particulièrement plastique.","changements":"aucun. Visage sculpté est déjà distinct du Visage volé vampirique (on sculpte d''après un modèle, on ne vole pas le visage d''une victime)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'sculpture_de_matiere', 'Sculpture de matière', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R — 1 PA","activation":null,"texte_court":"1 PA au contact. Remodèle jusqu''à 10 litres de matière inerte en une forme simple, sans changer sa composition. Travail délicat : Volonté + Force Mentale 15 et le savoir nécessaire. Pas d''attaque sur un corps vivant.","texte_reference":"Pour 1 PA au contact, remodelez jusqu’à 10 litres de matière inerte existante en une forme simple, sans en changer la composition. Une opération délicate demande Volonté + Force Mentale difficulté 15 et les connaissances nécessaires à la fonction produite.\nLa forme obtenue demeure matériellement stable si sa structure le permet. Ni transmutation, ni matière créée, ni savoir technique absent, ni attaque directe sur un corps vivant ; une arme reçoit un profil matériel approprié, pas un bonus gratuit.","lore":"Sous les mains du porteur, une matière solide révèle qu’elle n’est qu’une forme provisoire. Temps et précision permettent de déplacer ses volumes sans la transmuter en autre chose, comme un artisan travaillant un matériau devenu anormalement docile.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_sculpture_de_matiere']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'grand_remodelage', 'Grand remodelage', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"100 litres pour 2 PA, ou 1 m³ en dix minutes ; une structure complexe que tu sais concevoir. Matériaux et appuis restent réels.","texte_reference":"Sculpture de matière peut travailler jusqu’à 100 litres en 2 PA, ou 1 m³ après dix minutes, et former une structure complexe dont vous maîtrisez réellement la conception. Composition, matériaux, appuis et résistances physiques restent réels.\nUn espace occupé ne peut servir à enfermer ou écraser automatiquement une cible sans résolution appropriée ; aucune fabrication d’un appareil inconnu ou d’énergie gratuite.","lore":"Svenn permet de penser la forme à une échelle où plusieurs volumes doivent rester cohérents ensemble. Le sculpteur ne corrige plus un détail : il réorganise une structure entière sans cesser de respecter ce que sa matière peut réellement devenir.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_grand_remodelage']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'visage_sculpte', 'Visage sculpté', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — 1 PA","activation":null,"texte_court":"1 PA, jusqu''à la fin de la scène. Tes traits visibles changent dans ta morphologie actuelle, d''après un modèle observé ou une apparence choisie. Ni voix parfaite, ni biométrie, ni souvenirs ; tests d''imitation normaux.","texte_reference":"Pour 1 PA, modifiez vos traits visibles dans les limites de votre morphologie actuelle jusqu’à la fin de la scène, à partir d’un modèle observé ou d’une apparence définie. Imiter une personne ne donne ni ses souvenirs, ni sa voix parfaite, ni toutes ses signatures biométriques.\nPas de nouvelle Compétence ou hausse d’Attribut ; les contrôles d’imitation appropriés restent nécessaires. Une galerie ou fiche de modèle n’accorde pas une usurpation automatiquement réussie.","lore":"Svenn applique son art au masque le plus intime. Os, peau et proportions du visage se déplacent vers un modèle voulu, donnant au porteur une apparence reconstruite plutôt qu’une illusion posée par-dessus ses traits véritables.","statut_regle":"correction","changements":"aucun. Visage sculpté est déjà distinct du Visage volé vampirique (on sculpte d''après un modèle, on ne vole pas le visage d''une victime)."}'::jsonb, 'published', ARRAY['khinae_blood_visage_sculpte']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'sculpture_de_chair', 'Sculpture de chair', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"dix minutes au contact. Remodèle ton corps ou celui d''une cible consentante ou immobilisée, ou donne-lui pour la scène une adaptation : griffes DGT 3, peau Armure 1, membres palmés (+3 à la nage) ou sens mineur. Une adaptation à la fois ; un changement esthétique tient jusqu''à la fin du scénario. Cible hostile : Volonté + Force Mentale contre Défense occulte.","texte_reference":"Après dix minutes au contact, remodelez l’apparence de votre corps ou d’une cible consentante ou immobilisée, ou donnez-lui une adaptation corporelle simple définie à l’avance pour la scène. Une cible hostile résiste par Défense occulte contre Volonté + Force Mentale ; ni PV rendus, ni Nature ou signature racine copiée.\nRépertoire : griffes DGT 3, peau Armure corporelle 1, membres palmés donnant +3 aux tests de nage, ou faculté sensorielle mineure définie. Une adaptation à la fois ; une transformation esthétique peut tenir jusqu’à la fin du scénario. Pas de création d’organe vital manquant, de destruction interne automatique ou d’empilement de peaux et bonus de formes.","lore":"La chair devient une matière vivante que Svenn autorise à remodeler profondément. Muscles, proportions et traits peuvent être réorganisés lorsque le corps est offert ou maîtrisé, mais la transformation reste prisonnière de ce qu’un organisme de cette nature peut supporter.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_sculpture_de_chair']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_funeste', 'Sang Funeste · Verica', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_funeste","portes":{"A":"Les morts","B":"Le hurlement"},"identite":"mort, spectres, violence immatérielle","description":"Sang de Verica lié à la mort, aux spectres et à la violence immatérielle. Il rapproche le prédateur du monde des morts sans faire de lui un nécromancien universel.","changements":"phrase sur le palier suivant retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'vision_funeste', 'Vision funeste', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"à 10 m, les spectres présents et les traces de mort ou de violence intense. Une présence ou un résidu, pas le récit des faits.","texte_reference":"En SR/R, percevez les spectres présents et les traces perceptibles de mort ou de violence intense à 10 m. Vous identifiez une présence ou un résidu, sans obtenir automatiquement le déroulement des faits, les souvenirs du mort ou son identité.\nUne dissimulation surnaturelle adaptée reste opposable. Ce sens ne rappelle pas une âme déjà partie dans le Cycle.","lore":"Spectres et résidus de mort se détachent comme des blessures dans le décor. Le regard de Verica reconnaît les lieux où quelque chose a fini violemment et les présences qui n’ont pas entièrement quitté l’espace des vivants.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_vision_funeste']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'interroger_le_trepas', 'Interroger le trépas', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"1 PA. Quelques minutes d''échange avec un défunt présent à 10 m ou une empreinte de mort au contact. L''esprit garde sa volonté ; s''il refuse le contact, Volonté + Force Mentale contre sa Défense occulte. Il n''est tenu ni de répondre ni de dire vrai.","texte_reference":"Pour 1 PA, ouvrez pendant quelques minutes un échange avec un défunt encore présent à 10 m ou une empreinte de mort accessible au contact. Un esprit garde sa volonté ; une empreinte ne restitue que les éléments de l’événement qu’elle conserve réellement.\nPas de convocation d’une âme absente, de mensonge automatiquement percé ni de mémoire complète inventée. Si l’esprit s’oppose au seul contact, Volonté + Force Mentale affronte sa Défense occulte ; une réussite permet le dialogue, sans obliger à répondre ni à dire vrai.","lore":"La mort ne laisse parfois qu’une empreinte incapable de raconter plus qu’elle ne sait. Le porteur de Verica peut lui adresser quelques mots et recueillir ce qui subsiste encore, sans fabriquer de mémoire là où le défunt n’est déjà plus accessible.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_interroger_le_trepas']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'hurlement_funeste', 'Hurlement funeste', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — 1 PA","activation":null,"texte_court":"1 PA, 10 m, Volonté + Force Mentale contre la Défense occulte d''une cible incarnée. Au choix avant le jet : DGT 3 spirituels (l''Armure matérielle ne protège pas) ou −3 aux actions de concentration jusqu''à la fin de son prochain round.","texte_reference":"Pour 1 PA à 10 m, opposez Volonté + Force Mentale à la Défense occulte d’une cible incarnée directement perçue : DGT 3 spirituels, ou −3 aux actions de concentration jusqu’à la fin de son prochain round, au choix avant le jet. L’Armure matérielle ne protège pas ; les Protections spirituelles appropriées restent applicables.\nUne cible et un effet, pas les deux à la fois. Les dégâts suivent leur règle normale de résolution ; aucun second jet de Défense physique. Le palier supérieur ouvre explicitement la pleine cible immatérielle.","lore":"Le hurlement frappe là où une armure matérielle ne peut rien interposer. Verica charge le cri d’une violence destinée à l’esprit, capable d’atteindre directement ce qui anime un corps ou ce qui subsiste sans corps du tout.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_hurlement_funeste']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'cri_d_outre_tombe', 'Cri d''outre-tombe', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"le Hurlement atteint aussi les êtres immatériels, porte à 20 m et inflige DGT 6.","texte_reference":"Hurlement funeste atteint aussi les êtres immatériels et peut porter à 20 m avec DGT 6 au lieu de 3. Il garde 1 PA, la Défense occulte et le choix alternatif de trouble de concentration ; aucune attaque de zone gratuite.\nLes protections surnaturelles adaptées ne sont pas ignorées par le seul fait que l’Armure physique ne fonctionne pas.","lore":"La voix de Verica n’a pas besoin de chair pour trouver sa cible. Elle traverse le seuil qui sépare vivant et immatériel, portant jusqu’aux présences spirituelles la même violence vibratoire que les oreilles ordinaires entendent dans le monde physique.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_cri_d_outre_tombe']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_primal', 'Sang Primal · Khuyildar', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_primal","portes":{"A":"L''assimilation","B":"La brume"},"identite":"assimilation animale et brume","description":"Sang de Khuyildar fondé sur l’assimilation animale et la brume. Il explore la plasticité prédatrice de Khinae en ajoutant d’autres propriétés animales et des expressions corporelles plus fluides.","changements":"Brume défensive : **ressort propre validé** (l''allié adjacent), qui la sépare du Corps de brume vampirique. Rédaction resserrée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'assimilation_de_chair', 'Assimilation de chair', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"après avoir mangé un animal entier selon un rituel, tu apprends sa forme animale et ses propriétés physiques, fixées avec le MJ. La prendre coûte le PA d''une transformation animale. Ni Talent, ni Sang, ni profil hybride.","texte_reference":"Après consommation et rituel réels de l’animal entier selon l’espèce, enregistrez sa forme animale et ses propriétés physiques convenues. La prendre coûte le PA normal d’une transformation animale ; aucun Sang, Talent de Lignée, pouvoir unique ou profil hybride étranger n’est acquis.\nLes formes apprises conservent, leurs limites de taille, de milieu, de déplacement et d’équipement. Aucun pool de PV indépendant ni guérison à la transformation. Les ailes d’une forme acquise suivent leur profil de vol convenu, pas un vol sans limite ajouté par défaut.","lore":"Khuyildar exige une connaissance acquise par la prédation la plus concrète. Après avoir entièrement consommé un animal, le porteur conserve dans sa chair le souvenir de son anatomie et peut plus tard rappeler ce corps comme une forme possible.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_assimilation_de_chair']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'chimere_primale', 'Chimère primale', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"1 PA, pour la scène, combine deux propriétés simples de formes assimilées compatibles. Une seule Armure, une seule arme naturelle ; ni +1 PA ni régénération hybride. Ne s''ajoute pas à Chimère fonctionnelle.","texte_reference":"Pour 1 PA, combinez pour la scène deux propriétés simples provenant de formes animales réellement assimilées et physiquement compatibles. Une seule Armure corporelle, une seule valeur d’arme naturelle et aucun +1 PA, régénération hybride ou Talent étranger ne sont ajoutés.\nIl s’agit de traits définis — sens, nage, griffes, peau — et non des tableaux entiers de deux espèces. Ne se cumule pas avec Chimère fonctionnelle pour obtenir quatre propriétés ; retenir une seule configuration composite.","lore":"Plusieurs souvenirs animaux peuvent être convoqués sans exiger de choisir un corps complet. Une griffe, un sens, une peau ou une aptitude se combinent en une morphologie provisoire dont chaque trait vient d’une chair réellement assimilée.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_chimere_primale']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'brume_defensive', 'Brume défensive', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — Réaction 1 PA","activation":null,"texte_court":"Réaction, 1 PA. Une brume te couvre : Défense active physique à +3 contre l''attaque ; le PA comprend la défense. **Masquer la meute** : pour le même PA, la brume peut couvrir à la place un allié adjacent attaqué, qui gagne +3 à sa Défense active (il la paie normalement).","texte_reference":"Pour 1 PA en Réaction, produisez une brume protectrice et effectuez avec +3 la Défense active physique contre l’agression déclenchante. Le PA comprend la défense ; un effet mental direct ou une perception qui neutralise réellement la brume n’est pas contourné.\nLa défense exige la possibilité d’agir et n’autorise pas automatiquement la défense en Surprise. Le bonus ne s’ajoute pas à un couvert ou obscurcissement substantiellement équivalent.","lore":"La transformation se défait en vapeur au moment où l’agression arrive. Cette brume n’est pas une fuite complète : elle détourne juste assez la prise, le coup ou la trajectoire pour que le prédateur réapparaisse derrière une protection née de sa propre chair.","statut_regle":"correction","changements":"Brume défensive : **ressort propre validé** (l''allié adjacent), qui la sépare du Corps de brume vampirique. Rédaction resserrée."}'::jsonb, 'published', ARRAY['khinae_blood_brume_defensive']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'brume_gardienne', 'Brume gardienne', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R — maintien","activation":null,"texte_court":"1 PA, 1/scène. Une brume de 3 m de rayon autour de toi jusqu''à la fin de la scène, sans entretien. Les tirs qui la traversent subissent −3, quel que soit le camp.","texte_reference":"Pour 1 PA, une fois par scène, déployez autour de vous une brume de 3 m de rayon jusqu’à la fin de la scène sans PA d’entretien. Les tirs qui doivent la traverser subissent −3, quel que soit le camp, sauf perception adaptée qui neutralise réellement ce masquage.\nPas d’Armure, de dégâts, de protection mentale ou de cumul avec un autre malus équivalent de visibilité. La brume peut être abandonnée, mais ne fabrique pas de déplacement invisible automatique.","lore":"Khuyildar étend la brume autour du porteur jusqu’à en faire un petit territoire mouvant. Alliés et prédateur y trouvent un couvert surnaturel tandis que ceux qui veulent les atteindre doivent composer avec une visibilité et des appuis brouillés.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_brume_gardienne']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_chasseur', 'Sang Chasseur · Thorkel', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_chasseur","portes":{"A":"La marque","B":"La disparition"},"identite":"traque absolue et disparition","description":"Sang de Thorkel consacré à la traque absolue et à la disparition. Il pousse l’instinct de poursuite jusqu’à faire du porteur un prédateur spécialisé dans la conservation du contact et l’effacement de sa propre présence.","changements":"note de prix retirée (« 2 PTV : total 3 ») ; mention d''un « talent commun » à payer corrigée : Traque parfaite ne demande pas Traque infatigable."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'marque_indelebile', 'Marque indélébile', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"1 PA au contact. La cible porte ta signature jusqu''à la fin du scénario ; une marque à la fois. Tu la suis tant qu''une piste matérielle existe, sans connaître sa position à distance.","texte_reference":"Pour 1 PA au contact, marquez une cible d’une signature personnelle reconnaissable jusqu’à la fin du scénario ; une seule marque active à la fois. Vous pouvez la suivre tant qu’une piste reste matériellement possible, sans connaître sa position à distance.\nUn simple changement d’odeur ordinaire ne suffit pas à effacer la signature surnaturelle. Les ruptures dimensionnelles et contre-mesures réellement adaptées demeurent.","lore":"Le contact laisse sur la cible une signature que Thorkel rend intime au chasseur. Odeur et trace surnaturelle se mêlent en un repère personnel que la pluie, la foule ou les parfums ordinaires ne suffisent plus à rendre anonyme.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_marque_indelebile']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'traque_parfaite', 'Traque parfaite', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"sur ta cible marquée, temps, météo et perturbations ordinaires ne demandent plus de jet tant que la piste est continue. Seules des contre-mesures exceptionnelles ou surnaturelles s''y opposent.","texte_reference":"Pour la cible portant votre Marque indélébile, temps, météo et perturbations ordinaires ne demandent plus de jet tant qu’une continuité de piste existe. Seules les contre-mesures exceptionnelles ou surnaturelles adaptées ouvrent une opposition ; une téléportation ne laisse pas un itinéraire inventé.\nPrix de 2 PTV : total 3 avec la Marque, sans besoin de payer également le talent commun. Ne pas ajouter systématiquement un second bonus de +3.","lore":"Une fois la piste comprise, le temps et les intempéries cessent d’en gommer les signes les plus subtils. Le chasseur maintient le fil là où un pisteur ordinaire aurait déjà dû admettre qu’il n’y a plus rien à suivre.","statut_regle":"correction","changements":"note de prix retirée (« 2 PTV : total 3 ») ; mention d''un « talent commun » à payer corrigée : Traque parfaite ne demande pas Traque infatigable."}'::jsonb, 'published', ARRAY['khinae_blood_traque_parfaite']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'disparition', 'Disparition', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R — 1 PA, maintien","activation":null,"texte_court":"1 PA, puis 1 PA par round. Invisible au regard ordinaire tant que tu ne fais rien de violemment manifeste. Son, odeur, traces et capteurs adaptés te trouvent encore.","texte_reference":"Pour 1 PA puis 1 PA de maintien par round, devenez invisible au regard ordinaire tant que vous ne portez pas d’action violemment manifeste. Son, odeur, traces et capteurs réellement adaptés peuvent toujours vous localiser ; le pouvoir ne vous rend pas intangible.\nLe maintien s’arrête avec l’effet ; aucune attaque gratuite ou remise à zéro de l’Initiative. Le coût supplémentaire doit rester visible dans la fiche de forme.","lore":"Thorkel pousse l’art de l’approche jusqu’à retirer le prédateur de l’attention visible. La silhouette cesse réellement d’être trouvable par les yeux, mais la violence ouverte rompt cette faveur dès que la chasse devient affrontement.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_disparition']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'embuscade_parfaite', 'Embuscade parfaite', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"ta première attaque en quittant Disparition traite comme Surprise une cible qui ne t''avait pas localisé.","texte_reference":"Votre première attaque en quittant Disparition traite comme Surprise une cible qui ne vous avait pas réellement localisé. Cela ne lui retire pas un tour complet et les Talents autorisant explicitement une Défense active en Surprise restent utilisables.\nPas d’effacement magique d’une localisation déjà acquise. Une nouvelle activation d’invisibilité n’invente pas une nouvelle scène ou une perte automatique de la localisation.","lore":"Quitter l’invisibilité au moment exact de frapper transforme la chasse en rupture de perception. La proie reçoit l’attaque avant d’avoir reconstruit l’endroit où se trouve le prédateur, comme si l’espace lui avait rendu son ennemi une seconde trop tard.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_embuscade_parfaite']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_de_sagesse', 'Sang de Sagesse · Tomoko', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_de_sagesse","portes":{"A":"La mémoire","B":"La dévoration"},"identite":"mémoire et assimilation des savoirs","description":"Sang de Tomoko centré sur la mémoire et l’assimilation des savoirs. Sa prédation s’exprime moins par la force que par la capacité à conserver, incorporer et réutiliser ce qui a été appris.","changements":"notes de développement retirées (« Bibliothèque vivante sera différenciée… », consigne au MJ)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'memoire_absolue', 'Mémoire absolue', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"tu te rappelles avec précision tout ce que tu as appris ou observé. Un détail oublié par le joueur, le MJ te le rend. Rien de jamais acquis.","texte_reference":"Mémorisation extrêmement précise de ce que le Garou a réellement appris ou observé.\nNe fournit aucune information jamais acquise. Bibliothèque vivante sera différenciée par le rapprochement de souvenirs, non par le simple rappel d’un fait oublié par le joueur.","lore":"Un événement réellement observé ne s’efface presque plus. Visages, mots, disposition d’un lieu ou détails appris restent disponibles avec une netteté anormale, même longtemps après que la mémoire ordinaire aurait simplifié ou reconstruit la scène.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_memoire_absolue']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'bibliotheque_vivante', 'Bibliothèque vivante', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"SR","activation":null,"texte_court":"1/scène, 1 PA de réflexion. Le MJ te livre un rapprochement ou une contradiction déductible de tes souvenirs ; ton premier test intellectuel qui l''exploite gagne +3.","texte_reference":"Une fois par scène, après 1 PA de réflexion, retrouvez un rapprochement ou une contradiction objectivement déductible de vos souvenirs réels. Votre premier test intellectuel qui exploite cette déduction gagne +3 ; aucune information extérieure inconnue n’apparaît.\nLe détail simplement oublié par le joueur reste rappelable grâce à Mémoire absolue sans cet achat. Le MJ ne doit pas fabriquer une révélation lorsque les indices ne la permettent pas.","lore":"Tomoko ne laisse pas facilement disparaître ce qui a été réellement appris. Un détail oublié par l’attention consciente peut être retrouvé dans une mémoire profonde, comme un ouvrage mal rangé qu’un bibliothécaire intérieur sait encore localiser.","statut_regle":"correction","changements":"notes de développement retirées (« Bibliothèque vivante sera différenciée… », consigne au MJ)."}'::jsonb, 'published', ARRAY['khinae_blood_bibliotheque_vivante']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'devoration_de_savoir', 'Dévoration de savoir', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"après avoir mangé un organe adéquat d''un mort récent, +2 dans une Compétence qu''il possédait, pour la scène. Une seule à la fois.","texte_reference":"Après consommation réelle d’un organe adéquat d’un mort récent, gagnez +2 dans une Compétence qu’il possédait réellement, pour la scène. Une seule connaissance dévorée active ; aucun Talent, Sang, mémoire intégrale ou statut n’est acquis.\nLe domaine et la source sont définis avant le jet. La Compétence temporaire ne sert pas à acheter un prérequis permanent ; plusieurs organes ne s’additionnent pas.","lore":"Le savoir d’un mort peut laisser une trace jusque dans l’organe qui l’a servi. En le consommant, le porteur assimile pour un temps une compétence cohérente, mémoire étrangère suffisamment structurée pour guider ses gestes sans devenir sa propre expérience.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_devoration_de_savoir']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'heritage_de_chair', 'Héritage de chair', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"la Dévoration donne +3 au lieu de +2 et dure jusqu''à la fin du scénario.","texte_reference":"La connaissance obtenue par Dévoration de savoir donne +3 à la Compétence choisie, au lieu de +2, et demeure jusqu’à la fin du scénario. Elle ne se cumule pas avec la Dévoration de base et ne devient pas une acquisition permanente.\nUn spécialiste bénéficie lui aussi du +3 ; conserver une seule connaissance active et les prérequis matériels de consommation. Le profil ne réécrit pas les points de Compétence achetés.","lore":"Ce qui a été dévoré s’installe plus profondément dans la mémoire corporelle. La connaissance empruntée gagne en ampleur et persiste bien au-delà de l’instant initial, comme si Tomoko avait temporairement greffé un morceau de formation à son héritier.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_heritage_de_chair']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_enrage', 'Sang Enragé · Asulf', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_enrage","portes":{"A":"La fureur","B":"La contagion"},"identite":"Frénésie volontaire et contagion de la rage","description":"Sang d’Asulf consacré à la Frénésie volontaire. Il permet de traiter la rage prédatrice non comme un accident subi, mais comme un état dangereux que le porteur apprend à ouvrir, orienter puis refermer.","changements":"palier II de la porte B à **3 PTV**, coût d''origine conservé ; maîtrise de l''Enragé : 7 PTV. Corrections : « pas de Mue hybride pour Jayanti » réécrit, notes retirées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'fureur_croissante', 'Fureur croissante', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R — 1 PA","activation":null,"texte_court":"1 PA, tu entres volontairement en Frénésie. Tant qu''elle dure sans interruption : +1 aux tests physiques au premier round, +2 au deuxième, +3 ensuite.","texte_reference":"Entre volontairement en Frénésie. Tant qu’elle se poursuit sans interruption : +1 aux tests physiques par round, jusqu’à +3.\nAfficher +1 au premier round de Frénésie, +2 au suivant, +3 ensuite ; remise à zéro si elle s’interrompt. Le coût d’Impulsion et le malus de concentration demeurent sans Rage lucide ; pas de cumul automatique de Furies équivalentes.","lore":"Asulf autorise une Frénésie ouverte plutôt que subie. Tant que la rage continue d’être nourrie par l’affrontement, le corps s’y accorde de plus en plus, chaque seconde rendant la suivante plus violente et plus difficile à interrompre.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_fureur_croissante']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'rage_lucide', 'Rage lucide', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"en Frénésie volontaire, tu reconnais toujours tes proches et ignores le −3 aux actions de calme. L''Impulsion garde au moins 1 PA par round.","texte_reference":"En Frénésie volontaire, reconnaissez toujours vos proches réellement liés et ignorez le −3 aux actions exigeant calme et concentration. L’obligation de consacrer au moins 1 PA par round à l’Impulsion demeure ; les non-Loups conservent leur propre logique d’attachement.\nLa reconnaissance empêche de les traiter automatiquement comme ennemis sous le seul effet de cette Frénésie, pas de supprimer tout conflit volontaire. Ne fonctionne pas comme immunité générale à la domination.","lore":"La Frénésie reste une tempête, mais le porteur apprend à conserver quelques balises au milieu. Les siens gardent un visage reconnaissable et les gestes complexes restent possibles, même si l’impulsion de violence réclame toujours sa part.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_rage_lucide']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'morsure_furieuse', 'Morsure furieuse', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"1/scène par cible. Après une morsure payée qui inflige au moins 1 PV à un prédateur compatible, Volonté + Force Mentale contre sa Défense occulte : il entre en Frénésie. Son Impulsion suit son instinct, pas tes ordres. Ne transmet aucune Nature.","texte_reference":"Une fois par scène et par cible, après une morsure payée qui inflige au moins 1 PV réel à un prédateur compatible, opposez Volonté + Force Mentale à sa Défense occulte pour déclencher sa Frénésie. Son Impulsion suit la situation et son instinct, pas vos ordres ; les sorties normales restent possibles.\nL’opposition de l’effet secondaire n’ajoute pas une deuxième défense contre les dégâts de la morsure. Le pouvoir ne transmet aucune Nature et ne crée pas de Garou par infection.","lore":"La morsure porte avec elle l’état intérieur d’Asulf. Chez une créature dont l’instinct connaît déjà la rage prédatrice, cette contamination peut réveiller le même vertige de violence comme si la Frénésie avait été transmise par les crocs.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_morsure_furieuse']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'eveil_furieux', 'Éveil furieux', NULL, '{"nature":"sangs_vifs","cout":3,"cout_actuel":3,"palier":"II","porte":"B","palier_double":null,"acces":"R — 1/scénario","activation":null,"texte_court":"1 PA au contact, 1/scénario. Éveille un temps un héritage Khinae latent, ou permet à un allié descendant de Khinae, éveillé et consentant, une Mue hybride sans test d''épuisement, même après un échec narratif de Mue dans la scène. La Mue prend son round, compte dans l''épuisement et peut déclencher sa Frénésie. Ne lève pas un blocage HDS. Rien pour un porteur du Sang Enchaîné.","texte_reference":"Pour 1 PA au contact, une fois par scénario, vous pouvez éveiller temporairement un héritage Khinae réellement latent, ou permettre à un allié Khinae éveillé et consentant une Mue hybride sans test d’épuisement, même après un échec narratif de Mue dans la scène. La Mue prend son round complet, compte dans l’épuisement et peut provoquer la Frénésie prévue avec le MJ.\nLa seconde fonction est nouvelle. Pas de nouvelle Nature créée, de guérison, de copie des dons raciaux, de levée d’un HDS ou de Mue hybride pour Jayanti ; l’allié garde la possibilité de refuser. Aucun Compagnon gratuit : le latent demeure un individu réel.","lore":"Asulf peut heurter assez brutalement un héritage dormant pour le faire remonter à la surface. Chez un Garou latent, la Nature s’éveille dans la violence pour un temps, sans garantie que le corps ou l’esprit sorte indemne de cette ouverture forcée.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_eveil_furieux']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_enchaine', 'Sang Enchaîné · Jayanti', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_enchaine","portes":{"A":"Le corps","B":"L''entrave"},"identite":"le corps de guerre resté humain","description":"Sang de Jayanti qui remplace la forme hybride par un véritable corps de guerre humain révélé. Il conserve mains, armes et précision technique tout en développant une puissance surhumaine, mais interdit la Mue hybride selon les règles du Sang.","changements":"Corps Enchaîné quitte les traits de Nature (c''est un don du Sang). Vitesse impossible perd « même en étant Surpris » : la charte refuse les bonus défensifs permanents, et la Surprise est le levier de létalité du jeu (même logique que la correction Krovni). Notes retirées. Le Corps Enchaîné lui-même : question 1."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'corps_enchaine', 'Corps Enchaîné', NULL, '{"nature":"sangs_vifs","cout":0,"cout_actuel":0,"palier":"don","porte":null,"palier_double":null,"acces":null,"activation":null,"texte_court":"tu ne prends jamais la forme hybride. En humain révélé : +2 Vigueur, +2 Agilité, +1 PA par round à partir du deuxième round où tu es Révélé (B1 validé), Déplacement ×2, et tu gardes mains, armes, armures, véhicules et augmentations. Pas d''Armure 2, pas de DGT 5, pas de régénération de combat.","texte_reference":"tu ne prends jamais la forme hybride. En humain révélé : +2 Vigueur, +2 Agilité, +1 PA par round à partir du deuxième round où tu es Révélé (B1 validé), Déplacement ×2, et tu gardes mains, armes, armures, véhicules et augmentations. Pas d''Armure 2, pas de DGT 5, pas de régénération de combat.","lore":null,"statut_regle":"correction","changements":"Corps Enchaîné quitte les traits de Nature (c''est un don du Sang). Vitesse impossible perd « même en étant Surpris » : la charte refuse les bonus défensifs permanents, et la Surprise est le levier de létalité du jeu (même logique que la correction Krovni). Notes retirées. Le Corps Enchaîné lui-même : question 1."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'predateur_debout', 'Prédateur debout', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"en Révélé, +3 Pugilat et les prouesses physiques de ton corps Enchaîné.","texte_reference":"+3 aux tests de Pugilat et accès aux prouesses physiques correspondant à son corps Enchaîné.\nAppliquer +3 Pugilat seulement si acquis et actif en R, pas simplement si Sang Enchaîné est sélectionné. Ne donne ni DGT 5, ni Armure 2, ni régénération de combat.","lore":"Le corps de guerre de Jayanti reste vertical, précis et pleinement capable d’employer ses mains. Sa puissance n’imite pas un loup dressé : elle crée un prédateur humanoïde conçu pour lutter au contact sans sacrifier technique ni contrôle.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_predateur_debout']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'vitesse_impossible', 'Vitesse impossible', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R — 1/round","activation":null,"texte_court":"1/round en Révélé, une Défense active physique sans PA. **Pas en étant Surpris.**","texte_reference":"Une fois par round en R, effectuez une Défense active physique sans dépenser de PA, même en étant Surpris. Vous devez rester conscient et capable du geste ; aucun Déplacement gratuit supplémentaire ni +3 automatique n’est ajouté.\nRemplace, et ne complète pas, l’ancien effet. Une seule défense gratuite de ce type sur la même attaque ; les autres protections qui autorisent la Surprise ne donnent pas une deuxième Défense.","lore":"Le corps Enchaîné répond à une attaque évitée par un déplacement presque simultané. L’esquive devient déjà départ, transformant la fraction de seconde gagnée sur l’adversaire en changement brutal de position.","statut_regle":"correction","changements":"Corps Enchaîné quitte les traits de Nature (c''est un don du Sang). Vitesse impossible perd « même en étant Surpris » : la charte refuse les bonus défensifs permanents, et la Surprise est le levier de létalité du jeu (même logique que la correction Krovni). Notes retirées. Le Corps Enchaîné lui-même : question 1."}'::jsonb, 'published', ARRAY['khinae_blood_vitesse_impossible']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'griffe_d_entrave', 'Griffe d''entrave', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"1/round, une attaque naturelle payée fait jaillir une griffe DGT 3. Si elle inflige au moins 1 PV, la régénération automatique de la cible s''arrête jusqu''à la fin de son prochain round.","texte_reference":"Une fois par round, une attaque naturelle payée peut manifester une griffe DGT 3 ; si elle inflige au moins 1 PV réel, la régénération surnaturelle automatique de la cible est suspendue jusqu’à la fin de son prochain round. Les soins payés par action ou ressource restent possibles.\nLa griffe ne modifie pas une arme tenue, n’inflige pas de dégâts supplémentaires et ne cumule pas des durées. Les immunités spécifiques demeurent. ","lore":"Jayanti donne à l’attaque naturelle une fonction de verrou plutôt que de simple blessure. La plaie perturbe brièvement la faculté surnaturelle de se reconstruire, comme si la griffe avait accroché le processus de guérison lui-même.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_griffe_d_entrave']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'sceller_la_nature', 'Sceller la Nature', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"après ton attaque blessante, 1 PA en Réaction, 1/scène. Volonté + Force Mentale contre Défense occulte : un Talent de Vérité actif et identifié de la cible est inutilisable jusqu''à la fin de la scène.","texte_reference":"Après votre attaque blessante, pour 1 PA en Réaction une fois par scène, opposez Volonté + Force Mentale à la Défense occulte pour rendre inutilisable jusqu’à la fin de la scène un Talent de Vérité actif et identifié. Aucun don fondamental, passif, Nature, Armure innée ou choix de personnage n’est supprimé.\nLes dégâts et la blessure initiale sont résolus normalement ; l’opposition vise le scellement distinct. Le Talent revient à la fin de l’effet et ses PTV restent acquis. Respecter les contre-mesures et immunités écrites.","lore":"Une blessure peut devenir point d’ancrage contre la puissance qui l’a reçue. Le porteur de Jayanti cherche dans cette ouverture la manifestation active de Vérité et la force temporairement à se refermer sur elle-même.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_sceller_la_nature']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'sangs_vifs', 'sang_vengeur', 'Sang Vengeur · Astaphium', NULL, '{"nature":"garou, khinae","forme":"deux_portes","verrou":"ordre_paliers","sang":"sang_vengeur","portes":{"A":"Les plaies","B":"La Mue"},"identite":"plaies, douleur, violence de la Mue","description":"Sang d’Astaphium lié aux plaies, à la douleur et à la violence de la Mue. Il transforme les blessures et la souffrance du corps en vecteurs de riposte plutôt qu’en simple coût à encaisser.","changements":"phrase cassée corrigée (« une cicatrice esthétique… »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'hurlement_des_plaies', 'Hurlement des plaies', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R — 1 PA","activation":null,"texte_court":"1 PA, 10 m, Volonté + Force Mentale contre la Défense occulte d''une cible qui porte une blessure physique réelle : DGT 5 directs, sans Armure matérielle.","texte_reference":"Pour 1 PA à 10 m, opposez Volonté + Force Mentale à la Défense occulte d’une cible présentant une blessure physique encore réelle : DGT 5 directs, sans Armure matérielle. Une cible à pleine santé sans lésion exploitable n’est pas admissible.\n une cicatrice esthétique n’est pas encore une blessure active sans le palier suivant. Les Protections occultes pertinentes restent applicables ; une perte de maximum par transformation ne crée pas une lésion.","lore":"Le cri cherche uniquement la chair qui souffre déjà. Les blessures répondent comme si la vibration les connaissait une à une, s’ouvrant davantage sous une violence qui contourne l’armure parce qu’elle travaille à partir de lésions déjà présentes.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_hurlement_des_plaies']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'dechirer_les_cicatrices', 'Déchirer les cicatrices', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":null,"texte_court":"le Hurlement exploite aussi une Séquelle ou une ancienne blessure identifiée, même à PV pleins. En réussite, −3 aux actions physiques qui sollicitent la zone jusqu''à la fin de son prochain round.","texte_reference":"Hurlement des plaies peut aussi exploiter une Séquelle ou ancienne blessure physique réelle identifiée, même sur une cible à ses PV maximum. Une réussite impose en plus −3 aux actions physiques sollicitant la zone lésée jusqu’à la fin du prochain round de la cible.\nPas de Séquelle inventée, de baisse permanente d’Attribut ni de cumul de plusieurs −3 du même type. Les dégâts restent DGT 5, et la cible possède sa résistance occulte normale.","lore":"Astaphium reconnaît chaque ancienne blessure comme une porte déjà ouverte. Cicatrice, séquelle ou lésion mal refermée peut être rappelée à sa douleur première et devenir de nouveau le point faible autour duquel le corps s’effondre.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_dechirer_les_cicatrices']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'onde_de_mue', 'Onde de Mue', NULL, '{"nature":"sangs_vifs","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"à la fin d''une vraie Mue hybride, sans PA, Vigueur + Pugilat contre la Défense physique de chaque créature à 2 m, alliés compris. Réussite : elle recule de 2 m ou tombe, au choix avant le jet.","texte_reference":"À l’achèvement d’une véritable Mue hybride, sans PA supplémentaire, opposez Vigueur + Pugilat à la Défense physique des créatures à 2 m. Une réussite les fait reculer de 2 m ou les renverse, au choix avant résolution, sans dégâts automatiques.\nUn déclenchement par Mue complète, jamais par une simple transition R→V→R ou une Mue partielle. Aucun effet chez un Enchaîné privé de Mue hybride ; les créatures affectées ne sont pas choisies arbitrairement pour épargner les alliés.","lore":"Lorsque la forme hybride s’achève, le changement déborde du seul corps. Une poussée accompagne la Mue et bouscule ceux qui restent trop près, manifestation physique de la violence nécessaire pour faire surgir cette anatomie.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_onde_de_mue']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'sangs_vifs', 'mue_cataclysmique', 'Mue cataclysmique', NULL, '{"nature":"sangs_vifs","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":null,"texte_court":"l''Onde couvre 5 m et peut repousser ou attirer de 3 m au plus.","texte_reference":"Onde de Mue couvre 5 m et peut repousser ou attirer les créatures de 3 m au plus, selon l’opposition physique normale. Une seule onde par Mue ; aucun dégât ou deuxième Altération automatique ne s’ajoute.\nLes obstacles, masses et prises réelles restent pertinents. Pas d’entraînement à travers un mur ou de contournement du temps d’épuisement de Mue. Le personnage choisit le sens de l’onde, non les cibles une à une.","lore":"La transformation libère une onde assez puissante pour choisir son sens. Les corps proches peuvent être chassés loin du porteur ou au contraire happés vers lui, comme si la naissance de la forme hybride déplaçait brutalement l’espace autour d’elle.","statut_regle":"origine","changements":null}'::jsonb, 'published', ARRAY['khinae_blood_mue_cataclysmique']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
